import { execFile } from 'node:child_process';

// A TokenProvider yields the bearer token the HttpClient sends to an ArgoCD
// instance. Static tokens are returned as-is; command-backed tokens are
// generated by an external program and refreshed when they expire, which is
// what lets the server sit behind an identity-aware proxy (GCP IAP, …) or ride
// on an SSO session (the argocd CLI's Dex/OIDC token) without ever holding a
// long-lived credential.
export interface TokenProvider {
  // Short, secret-free label for logs and error messages.
  readonly description: string;
  // Resolve the token to use for the next request. Rejects (never resolves to
  // an empty string) when no token can be obtained.
  getToken(): Promise<string>;
  // Drop any cached token so the next getToken() obtains a fresh one. Returns
  // true when a fresh token can actually be obtained, false when the provider
  // has nothing else to offer (a static token) — callers use this to decide
  // whether a request rejected as unauthenticated is worth retrying.
  invalidate(): boolean;
}

export class StaticTokenProvider implements TokenProvider {
  public readonly description = 'static token';

  constructor(private readonly token: string) {}

  public getToken(): Promise<string> {
    return Promise.resolve(this.token);
  }

  public invalidate(): boolean {
    return false;
  }
}

export type CommandTokenProviderOptions = {
  // Executable followed by its arguments. Run directly, never via a shell.
  command: string[];
  // How long a generated token is reused before the command is run again.
  ttlSeconds?: number;
  // How long to wait for the command before giving up.
  timeoutSeconds?: number;
};

// Defaults chosen for the common case of ~1h cloud identity tokens: refresh
// well before expiry, and never let a hung helper stall tool calls for long.
export const DEFAULT_TOKEN_TTL_SECONDS = 2700;
export const DEFAULT_TOKEN_COMMAND_TIMEOUT_SECONDS = 10;

// Generous enough for any realistic token; small enough that a misbehaving
// helper that floods stdout is cut off rather than buffered indefinitely.
const MAX_OUTPUT_BYTES = 1024 * 1024;

type CachedToken = { token: string; expiresAt: number };

export class CommandTokenProvider implements TokenProvider {
  public readonly description: string;
  private readonly command: string[];
  private readonly ttlMs: number;
  private readonly timeoutMs: number;
  private readonly now: () => number;
  private cached?: CachedToken;
  // The single in-flight execution shared by every caller that misses the
  // cache at the same time, so a burst of tool calls spawns one process.
  private inflight?: Promise<string>;

  constructor(options: CommandTokenProviderOptions, deps: { now?: () => number } = {}) {
    const { command, ttlSeconds = DEFAULT_TOKEN_TTL_SECONDS, timeoutSeconds } = options;
    if (
      !Array.isArray(command) ||
      !command.every((part) => typeof part === 'string') ||
      !command[0]
    ) {
      throw new Error('tokenCommand must be a non-empty array of strings');
    }
    if (!isPositiveNumber(ttlSeconds)) {
      throw new Error('tokenTTLSeconds must be a positive number');
    }
    const timeout = timeoutSeconds ?? DEFAULT_TOKEN_COMMAND_TIMEOUT_SECONDS;
    if (!isPositiveNumber(timeout)) {
      throw new Error('tokenCommandTimeoutSeconds must be a positive number');
    }
    this.command = [...command];
    this.ttlMs = ttlSeconds * 1000;
    this.timeoutMs = timeout * 1000;
    this.now = deps.now ?? Date.now;
    // Arguments routinely carry identifiers (audiences, account names) that
    // should not end up in logs, so only the executable is named.
    this.description = `command "${command[0]}"`;
  }

  public async getToken(): Promise<string> {
    if (this.cached && this.cached.expiresAt > this.now()) {
      return this.cached.token;
    }
    if (!this.inflight) {
      this.inflight = this.run()
        .then((token) => {
          this.cached = { token, expiresAt: this.now() + this.ttlMs };
          return token;
        })
        .finally(() => {
          this.inflight = undefined;
        });
    }
    return this.inflight;
  }

  public invalidate(): boolean {
    this.cached = undefined;
    return true;
  }

  private run(): Promise<string> {
    const [file, ...args] = this.command;
    const timeoutSeconds = this.timeoutMs / 1000;
    return new Promise<string>((resolve, reject) => {
      execFile(
        file,
        args,
        {
          timeout: this.timeoutMs,
          maxBuffer: MAX_OUTPUT_BYTES,
          encoding: 'utf8',
          windowsHide: true
        },
        (error, stdout, stderr) => {
          if (error) {
            const failure = error as NodeJS.ErrnoException & { killed?: boolean; code?: unknown };
            // Node reports a timeout as a SIGTERM-killed process; surface it
            // as such rather than as an opaque "null exit code".
            if (failure.killed && failure.signal) {
              reject(
                new Error(`${this.description} timed out after ${timeoutSeconds}s${detail(stderr)}`)
              );
            } else if (typeof failure.code === 'number') {
              reject(
                new Error(`${this.description} exited with code ${failure.code}${detail(stderr)}`)
              );
            } else {
              // Spawn failures (ENOENT, EACCES, …): the code is the errno string.
              reject(new Error(`${this.description} could not be run: ${failure.message}`));
            }
            return;
          }
          const token = stdout.trim();
          if (!token) {
            reject(new Error(`${this.description} produced no output${detail(stderr)}`));
            return;
          }
          resolve(token);
        }
      );
    });
  }
}

const isPositiveNumber = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value) && value > 0;

// A trimmed excerpt of stderr for error messages: helpers like gcloud/argocd
// put the actionable hint ("not logged in", "run … login") there. stdout is
// deliberately never included, since that is where the token would be.
const detail = (stderr: string): string => {
  const text = stderr.trim().split('\n').slice(-3).join(' ').slice(0, 300);
  return text ? `: ${text}` : '';
};
